import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import './login.css';

const FindPasswordPage = () => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    name: '',
    email: ''
  });
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [foundPassword, setFoundPassword] = useState('');

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));

    // 입력 시 에러 메시지 클리어
    if (error) {
      setError('');
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    // 이메일 입력 확인
    if (!email) {
      setError('이메일을 입력해주세요.');
      setIsLoading(false);
      return;
    }

    // 이메일 형식 검사
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
      setError('올바른 이메일 형식을 입력해주세요.');
      setIsLoading(false);
      return;
    }

    try {
      // 여기에 실제 비밀번호 재설정 API 호출을 추가하세요
      console.log('비밀번호 재설정 요청:', email);

      // 임시 로직 (실제 구현 시 Spring Boot API와 연동)
      await new Promise(resolve => setTimeout(resolve, 2000)); // 2초 대기

      // 성공 시 처리
      setIsEmailSent(true);

    } catch (err) {
      setError('이메일 전송에 실패했습니다. 다시 시도해주세요.');
      console.error('비밀번호 재설정 에러:', err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleBackToLogin = () => {
    navigate('/login');
  };

  if (isEmailSent) {
    return (
      <div className="login-container">
        <div className="login-box">
          <div className="login-header">
            <h2>이메일이 전송되었습니다</h2>
            <p>비밀번호 재설정 링크를 확인해주세요</p>
          </div>

          <div style={{ textAlign: 'center', margin: '30px 0' }}>
            <div style={{ 
              fontSize: '3rem', 
              color: '#667eea', 
              marginBottom: '20px' 
            }}>
              ✉️
            </div>
            <p style={{ 
              color: '#666', 
              lineHeight: '1.6',
              marginBottom: '20px'
            }}>
              <strong>{email}</strong>로<br/>
              비밀번호 재설정 링크를 전송했습니다.<br/>
              이메일을 확인하고 링크를 클릭해주세요.
            </p>
            <p style={{ 
              fontSize: '0.85rem', 
              color: '#888' 
            }}>
              이메일이 오지 않았다면 스팸함을 확인해주세요.
            </p>
          </div>

          <button 
            type="button" 
            className="login-button"
            onClick={handleBackToLogin}
          >
            로그인 페이지로 돌아가기
          </button>

          <div className="login-footer">
            <div className="signup-link">
              <button 
                type="button"
                onClick={() => setIsEmailSent(false)}
                style={{
                  background: 'none',
                  border: 'none',
                  color: '#667eea',
                  textDecoration: 'underline',
                  cursor: 'pointer',
                  fontSize: '0.9rem',
                  fontWeight: '500'
                }}
              >
                다른 이메일로 다시 시도
              </button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="login-container">
      <div className="login-box">
        <div className="login-header">
          <h2>비밀번호 찾기</h2>
          <p>가입하신 이메일을 입력해주세요</p>
        </div>

        <form onSubmit={handleSubmit} className="login-form">
          <div className="form-group">
            <label htmlFor="email">이메일</label>
            <input
              type="email"
              id="email"
              name="email"
              value={email}
              onChange={handleEmailChange}
              placeholder="가입하신 이메일을 입력하세요"
              required
              disabled={isLoading}
            />
          </div>

          {error && (
            <div className="error-message">
              {error}
            </div>
          )}

          <button 
            type="submit" 
            className="login-button"
            disabled={isLoading}
          >
            {isLoading ? (
              <>
                <span className="spinner"></span>
                이메일 전송 중...
              </>
            ) : (
              '비밀번호 재설정 이메일 전송'
            )}
          </button>
        </form>

        <div className="login-footer">
          <div className="signup-link">
            <span>이미 계정 정보를 기억하셨나요? </span>
            <button 
              type="button"
              onClick={handleBackToLogin}
              style={{
                background: 'none',
                border: 'none',
                color: '#667eea',
                textDecoration: 'underline',
                cursor: 'pointer',
                fontSize: '0.9rem',
                fontWeight: '500'
              }}
            >
              로그인
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default FindPasswordPage;
